/* cppi::89470d9bb29adf74a26dcf71b91a3961711e02ae9cc51464f65055069472fe85 */
select 
case when cast(substring('2025-06-20', 6, 2) as integer) <= 3 then  (substring('2025-06-20', 1, 4)||'-03-28')
else  cast(cast(substring('2025-06-20', 1, 4) as integer)+1 as varchar)||'-03-28' end as TEST_AFTER0328,
case when cast(substring('2025-03-20', 6, 2) as integer) <= 3 then  (substring('2025-03-20', 1, 4)||'-03-28')
else  cast(cast(substring('2025-03-20', 1, 4) as integer)+1 as varchar)||'-03-28' end as TEST_BEFORE328

