/* cppi::527a3a62f8fae008cebfc7b57091b9a2a34651399c3a54525fd52c9c7793de3c */
select business_date as date_, security_id, 'SP500_30' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-19' and business_date <= date '2025-06-19' and weight_ndo>0 and id_cppib_index = 'SP500_30_GR_USD_0_0' and security_id is not null

/* cppi::e2cadd84cfe5198e329c4f32e15615facab68f09ece387920597a75460ab6200 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-23' and end_date = '2025-05-23')
and start_date = '2025-05-23' and end_date = '2025-05-23'

